"use client";

import * as React from "react";
import { useFlowGroup } from "@/lib/sahajiv-motion/use-flow";
import { useMorph } from "@/lib/sahajiv-motion/use-morph";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { OTPInput, OTPInputContext, REGEXP_ONLY_DIGITS } from "input-otp";
export const inputOTPVariants = cva("v-otp flex gap-[var(--s-2)]");
export type InputOTPProps = React.ComponentProps<typeof OTPInput>;
export function InputOTP({
  containerClassName,
  className,
  pattern = REGEXP_ONLY_DIGITS,
  ...props
}: InputOTPProps) {
  return (
    <OTPInput
      data-slot="input-otp"
      data-part="root"
      data-otp=""
      containerClassName={cn(inputOTPVariants(), containerClassName)}
      className={className}
      pattern={pattern}
      {...props}
    />
  );
}
export type InputOTPGroupProps = React.ComponentProps<"div">;
export function InputOTPGroup({
  className,
  ref,
  ...props
}: InputOTPGroupProps) {
  const morphRef = useMorph<HTMLDivElement>("inputs", ref);
  const flowRef = useFlowGroup<HTMLDivElement>(morphRef, {
    kind: "fill",
    itemSelector: '[data-slot="input-otp-slot"]',
    activeSelector: '[data-state="active"]',
  });
  return (
    <div
      ref={flowRef}
      data-slot="input-otp-group"
      data-flow-fields="auto"
      className={cn("v-otp flex gap-[var(--s-2)]", className)}
      {...props}
    />
  );
}
export type InputOTPSlotProps = React.ComponentProps<"div"> & { index: number };
export function InputOTPSlot({
  className,
  index,
  ...props
}: InputOTPSlotProps) {
  const context = React.useContext(OTPInputContext);
  const slot = context.slots[index];
  return (
    <div
      data-slot="input-otp-slot"
      data-part="item"
      data-active={slot?.isActive || undefined}
      data-state={slot?.isActive ? "active" : "inactive"}
      className={cn("grid place-items-center relative", className)}
      {...props}
    >
      {slot?.char}
      {slot?.hasFakeCaret && (
        <span aria-hidden="true" className="absolute h-5 w-px bg-current" />
      )}
    </div>
  );
}
export type InputOTPSeparatorProps = React.ComponentProps<"div">;
export function InputOTPSeparator({
  children,
  ...props
}: InputOTPSeparatorProps) {
  return (
    <div data-slot="input-otp-separator" role="separator" {...props}>
      {children ?? "−"}
    </div>
  );
}

@layer sahajiv-states {
/* SahaJiv authored subparts, state precedence, and irreducible shapes; scoped to this registry item. */
.v-otp:where([data-slot="input-otp"], [data-slot^="input-otp-"]) {
  display: flex;
  gap: var(--s-2);
}
[data-slot="input-otp-slot"] {
  width: 44px;
  height: 52px;
  text-align: center;
  font-size: 20px;
  font-weight: 600;
  border-radius: var(--r-md);
  background: var(--v-beige);
  border: 1.5px solid transparent;
}
[data-slot="input-otp-slot"][data-active] {
  outline: 0;
  border-color: var(--v-pink);
}
@media (max-width: 640px) {
  .v-otp:where([data-slot="input-otp"], [data-slot^="input-otp-"]) {
    gap: 6px;
  }
}
@media (max-width: 640px) {
  [data-slot="input-otp-slot"] {
    flex: 1 1 0;
    min-width: 0;
    width: auto;
  }
}
[data-slot="input-otp-slot"] {
  box-shadow: inset 0 0 0 1px var(--v-edge);
}
[data-slot="input-otp-slot"][data-active] {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}
[data-slot="input-otp-slot"]:nth-child(3) {
  margin-right: 12px;
}
[data-slot="input-otp-slot"] {
  transition:
    box-shadow var(--t-micro),
    background var(--t-micro),
    transform var(--t-micro) var(--enter);
}
[data-slot="input-otp-slot"][data-active] {
  transform: translateY(-2px);
}
.v-otp:where([data-slot="input-otp"], [data-slot^="input-otp-"]) {
  box-shadow: none;
  border: 0;
}
[data-slot="input-otp-slot"] {
  border: 1.5px solid var(--v-border);
  background: var(--input);
  box-shadow: none;
}
[data-slot="input-otp-slot"][data-active] {
  border-color: var(--v-pink);
}
[data-slot="input-otp-slot"] {
  border-color: var(--v-edge);
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="input-otp"],
  [data-slot^="input-otp-"],
  [data-slot="input-otp"]::before,
  [data-slot="input-otp"]::after,
  [data-slot^="input-otp-"]::before,
  [data-slot^="input-otp-"]::after {
    animation-duration: 0s;
    animation-iteration-count: 1;
    transition-duration: 0s;
    scroll-behavior: auto;
  }
}

[data-slot="input-otp-group"] {
  flex: 1;
  min-height: 0;
}
[data-slot="input-otp-slot"] {
  flex-shrink: 0;
}
[data-slot="input-otp-slot"][data-active] {
  border-color: var(--v-pink);
}
[data-slot="input-otp"]:disabled {
  cursor: not-allowed;
}

/* Preserve the authored native input inset on the semantic visual slots. */
[data-slot="input-otp-slot"] { padding: 1px 2px; }

}
